require_once __DIR__.'/includes/bootstrap.php';$count=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($count)$errors[]='An admin already exists. Delete this setup file.';$n=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';if(!valid_name($n))$errors[]='Enter a valid name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!strong_password($p))$errors[]='Password needs 8+ characters, letters and numbers.';if(!$errors){$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='Email already registered.';else{$s=db()->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'admin')");$s->execute([$n,$email,password_hash($p,PASSWORD_DEFAULT)]);set_flash('success','Admin created. Delete setup-admin.php now.');redirect('login.php');}}}render_header('Admin setup');?><section class="panel form-panel narrow"><p class="eyebrow">ONE-TIME SETUP</p><h1>Create first admin</h1><p class="muted">Use once after importing schema.sql. Delete this file immediately after creating the admin.</p><?php if($count):?><div class="alert error">An admin already exists. Delete setup-admin.php.</div><?php endif;?><?php if($errors):?><div class="alert error"><?php foreach($errors as $x)echo '<p>'.e($x).'</p>';?></div><?php endif;?><?php if(!$count):?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Full name<input name="full_name" required></label><label>Admin email<input type="email" name="email" required></label><label>Strong password<input type="password" name="password" required></label><button class="btn">Create admin</button></form><?php endif;?></section><?php render_footer();?>
